/* QuickSight 9f7029d3-8f01-4346-af06-bd706c3d9a4f */
SELECT "node", "hierarchy_level", "hierarchy_type", "node_level", "account", "pool", "portfolio_type", "active_risk_benchmark", "department", "strategy", "program", "sub_program", "model_portfolio", "analytic_name", "analytic_type", "analytic_value", "override_source", "override_value", "scaling_type", "currency", "curve", "curve_type", "tenor", "methodology", "rating", "confidence_level", CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS "business_date"
FROM "AwsDataCatalog"."risk_prod"."rmv_analytics"
WHERE CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) > from_unixtime(cast(substr(cast(1749553430173 as varchar), 1, 10) AS bigint))

/* cppi::36e909752de6422137e75d40cb2c6d3b8f16d1f47b895c610569efa69b5392ce */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-11' and business_date <= date '2025-06-11' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

